#include <stddef.h>
#include <stdio.h>

typedef int Row4[4];

static void print_values(const int *data, size_t count)
{
    size_t i;
    for (i = 0U; i < count; ++i) {
        printf("%d%s", data[i], i + 1U == count ? "\n" : " ");
    }
}

int main(void)
{
    int values[4] = {10, 20, 30, 40};
    int *pointers[4] = {
        &values[0], &values[1], &values[2], &values[3]
    };
    int (*row_pointer)[4] = &values;
    const int *read_only_pointer = &values[0];
    int *const fixed_pointer = &values[1];
    const int *const fixed_read_only_pointer = &values[2];
    Row4 *row_alias_pointer = &values;
    volatile int device_status = 1;
    size_t i;

    *fixed_pointer = 25;
    printf("Array through pointer-to-array: ");
    print_values(*row_pointer, 4U);

    printf("Array of pointers: ");
    for (i = 0U; i < 4U; ++i) {
        printf("%d%s", *pointers[i], i == 3U ? "\n" : " ");
    }

    printf("Read-only view: %d\n", *read_only_pointer);
    printf("Fixed read-only view: %d\n", *fixed_read_only_pointer);
    printf("Typedef array view: %d\n", (*row_alias_pointer)[3]);
    printf("Volatile status sample: %d\n", device_status);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

typedef int (*BinaryOperation)(int, int);

static int add(int left, int right)
{
    return left + right;
}

static int subtract(int left, int right)
{
    return left - right;
}

static int multiply(int left, int right)
{
    return left * right;
}

static int *select_slot(int *values, size_t count, size_t index)
{
    if (values == NULL || index >= count) {
        return NULL;
    }
    return &values[index];
}

static void print_matrix(size_t rows, const int (*matrix)[3])
{
    size_t row;
    size_t column;

    for (row = 0U; row < rows; ++row) {
        for (column = 0U; column < 3U; ++column) {
            printf("%d%s", matrix[row][column],
                   column == 2U ? "\n" : " ");
        }
    }
}

int main(void)
{
    BinaryOperation operations[3] = {add, subtract, multiply};
    const char *const operation_names[3] = {"add", "subtract", "multiply"};
    int values[3] = {4, 5, 6};
    int matrix[2][3] = {{1, 2, 3}, {4, 5, 6}};
    size_t i;
    int *selected = select_slot(values, 3U, 1U);
    int *missing = select_slot(values, 3U, 9U);

    for (i = 0U; i < 3U; ++i) {
        printf("%s(9, 3) = %d\n",
               operation_names[i], operations[i](9, 3));
    }

    if (selected != NULL) {
        *selected = 50;
    }
    printf("Selected array element: %d\n", values[1]);
    printf("Out-of-range selection: %s\n",
           missing == NULL ? "NULL" : "unexpected pointer");

    puts("Matrix passed through a pointer-to-array parameter:");
    print_matrix(2U, matrix);
    return 0;
}
